import{_ as t}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as a,o as i,c as r,al as o}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"Return Mode (VTOL)","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_modes_vtol/return.md","filePath":"en/flight_modes_vtol/return.md"}'),n={name:"en/flight_modes_vtol/return.md"};function l(d,e,s,h,c,_){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="return-mode-vtol" tabindex="-1">Return Mode (VTOL) <a class="header-anchor" href="#return-mode-vtol" aria-label="Permalink to &quot;Return Mode (VTOL)&quot;">​</a></h1><img src="'+t+'" title="Position fix required (e.g. GPS)" width="30px"><p>The <em>Return</em> flight mode is used to <em>fly a vehicle to safety</em> on an unobstructed path to a safe destination, where it may either wait (hover or circle) or land.</p><p>VTOL vehicles use the <a href="./../flight_modes/return#rtl_type_1">Mission Landing/Rally Point</a> return type by default. In this return type a vehicle ascends to a minimum safe altitude above obstructions (if needed), and then flies directly to a rally point or the start of a mission landing point (whichever is nearest), or the home position if neither rally points or mission landing pattern is defined. If the destination is a mission landing pattern, the vehicle will then follow the pattern to land. If the destination is a rally point or the home location, the vehicle will fly to that destination and land.</p><p>The vehicle will return using the flying mode (MC or FW) it was using at the point when return mode was triggered. Generally it will follow the same return mode behaviour of the corresponding vehicle type, but will always transition to MC mode (if needed) before landing.</p><p>VTOL supports the <a href="./../flight_modes/return#return_types">other PX4 return types</a>, including home/rally point return, mission path and closest safe destination. The default type is recommended.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Mode is automatic - no user intervention is <em>required</em> to control the vehicle.</li><li>Mode requires a global 3d position estimate (from GPS or inferred from a <a href="./../ros/external_position_estimation#enabling-auto-modes-with-a-local-position">local position</a>). <ul><li>Flying vehicles can&#39;t switch to this mode without global position.</li><li>Flying vehicles will failsafe if they lose the position estimate.</li></ul></li><li>Mode requires home position is set.</li><li>Mode prevents arming (vehicle cannot be armed while this mode is selected).</li><li>RC control switches can be used to change flight modes on any vehicle.</li><li>RC stick movement is ignored.</li></ul></div><h2 id="technical-summary" tabindex="-1">Technical Summary <a class="header-anchor" href="#technical-summary" aria-label="Permalink to &quot;Technical Summary&quot;">​</a></h2><p>VTOL vehicles use the <a href="./../flight_modes/return#rtl_type_1">Mission Landing/Rally Point</a> return type by default, and return using the flying mode (MC or FW) it was using at the point when return mode was triggered.</p><h3 id="fixed-wing-mode-fw-return" tabindex="-1">Fixed-wing Mode (FW) Return <a class="header-anchor" href="#fixed-wing-mode-fw-return" aria-label="Permalink to &quot;Fixed-wing Mode (FW) Return&quot;">​</a></h3><p>If returning as a fixed-wing, the vehicle:</p><ul><li><p>Ascends to a safe minimum return altitude defined by <a href="#RTL_RETURN_ALT">RTL_RETURN_ALT</a> (safely above any expected obstacles). The vehicle maintains its initial altitude if that is higher than the minimum return altitude.</p></li><li><p>Flies via a constant-altitude path to the destination, which will be the closest of the start of a <em>mission landing pattern</em> and any rally point, or the home location if no mission landing pattern or rally points are defined. The path is chosen to be the shortest horizontal <a href="./../flight_modes/return#geofence_awareness">geofence-aware path</a>.</p></li><li><p>If the destination is a mission landing pattern it will follow the pattern to land.</p><p>A mission landing pattern for a VTOL vehicle consists of a <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_LAND_START" target="_blank" rel="noreferrer">MAV_CMD_DO_LAND_START</a>, one or more position waypoints, and a <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_VTOL_LAND" target="_blank" rel="noreferrer">MAV_CMD_NAV_VTOL_LAND</a>.</p></li><li><p>If the destination is a rally point or home it will:</p><ul><li><p>Fly to the selected <a href="#vtol-rally-point-approach-loiters">VTOL approach loiter</a> associated with that landing location (if any are defined) and use it to descend to the approach altitude. If several approach loiters are defined for that location, PX4 chooses the one that best matches the estimated wind at the landing point.</p><p>See <a href="#vtol-rally-point-approach-loiters">VTOL Rally Point Approach Loiter</a> below for information on how to define approach loiters (using <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TO_ALT" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TO_ALT</a> items in your <em>rally plan</em>).</p></li><li><p>Loiter/spiral down to the approach altitude, or to <a href="#RTL_DESCEND_ALT">RTL_DESCEND_ALT</a> above the destination if no approach altitude is defined.</p></li><li><p>Circle for a short time, as defined by <a href="#RTL_LAND_DELAY">RTL_LAND_DELAY</a>.</p></li><li><p>Fly from the approach loiter to the return destination (the rally point or home location).</p></li><li><p>Transition to MC mode at the destination and land.</p><p>Note that <a href="./../advanced_config/parameter_reference#NAV_FORCE_VT">NAV_FORCE_VT</a> is ignored: the vehicle will always land as a multicopter for these destinations.</p></li></ul></li></ul><h4 id="vtol-rally-point-approach-loiters" tabindex="-1">VTOL Rally Point Approach Loiters <a class="header-anchor" href="#vtol-rally-point-approach-loiters" aria-label="Permalink to &quot;VTOL Rally Point Approach Loiters&quot;">​</a></h4><p>VTOL <em>rally point approach loiters</em> are <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TO_ALT" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TO_ALT</a> items associated with a particular rally point (<a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_RALLY_POINT" target="_blank" rel="noreferrer">MAV_CMD_NAV_RALLY_POINT</a>) in a <a href="./../flying/plan_safety_points">Rally plan</a>. They define options for where the VTOL can descend to the rally point approach altitude, and how it will approach the rally point. Several approach loiters can be defined for a rally point, and PX4 will choose the one that best matches the estimated wind at the landing point.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <code>MAV_CMD_NAV_LOITER_TO_ALT</code> items that define approach loiters are associated with a Rally/safety point, and are hence part of the rally point plan when used in this way — <em>not</em> the mission plan. This behaviour is not defined in the MAVLink rally point plan specification.</p></div><p>When uploading VTOL approach loiters through MAVLink, <a href="https://mavlink.io/en/services/mission.html#mission_types" target="_blank" rel="noreferrer">upload them as rally/safe-point</a> mission items (<code>MAV_MISSION_TYPE_RALLY</code>). The <code>MAV_CMD_NAV_RALLY_POINT</code> item must come first, followed by one or more <code>MAV_CMD_NAV_LOITER_TO_ALT</code> items that define the approach loiters for that rally point. The next <code>MAV_CMD_NAV_RALLY_POINT</code> starts a new landing-location block.</p><p>For each <code>MAV_CMD_NAV_LOITER_TO_ALT</code> item, <code>x/y/z</code> define the loiter center and approach altitude, and <code>param2</code> defines the loiter radius used by RTL. If <code>param2</code> is unset or zero, PX4 falls back to <a href="#RTL_LOITER_RAD">RTL_LOITER_RAD</a>.</p><p>For example, a rally upload with one rally point and two possible approach loiters would use:</p><table tabindex="0"><thead><tr><th>Sequence</th><th>Command</th><th>Purpose</th><th>Key fields</th></tr></thead><tbody><tr><td>0</td><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_RALLY_POINT" target="_blank" rel="noreferrer">MAV_CMD_NAV_RALLY_POINT</a></td><td>Landing location</td><td><code>x/y/z</code>: rally latitude, longitude, altitude</td></tr><tr><td>1</td><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TO_ALT" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TO_ALT</a></td><td>First VTOL approach loiter</td><td><code>x/y/z</code>: loiter latitude, longitude, altitude; <code>param2</code>: loiter radius</td></tr><tr><td>2</td><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TO_ALT" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TO_ALT</a></td><td>Second VTOL approach loiter</td><td><code>x/y/z</code>: loiter latitude, longitude, altitude; <code>param2</code>: loiter radius</td></tr></tbody></table><p>Note that the approach loiter is not the back-transition point. If the selected approach loiter is far from the rally point or home location, the vehicle remains in fixed-wing mode after the loiter, flies to the destination at the approach altitude, and only then back-transitions for landing.</p><h2 id="multicopter-mode-mc-return" tabindex="-1">Multicopter Mode (MC) Return <a class="header-anchor" href="#multicopter-mode-mc-return" aria-label="Permalink to &quot;Multicopter Mode (MC) Return&quot;">​</a></h2><p>If returning as a multicopter:</p><ul><li>The behaviour is the same except that the vehicle flies as a multicopter and respects multicopter settings.</li><li>In particular, if landing on rally point or the home position the vehicle uses the <a href="#RTL_CONE_ANG">RTL_CONE_ANG</a> instead of just the <a href="#RTL_RETURN_ALT">RTL_RETURN_ALT</a> for defining the minimum safe return altitude. For more information see the explanation of the &quot;cone&quot; in <a href="./../flight_modes/return#minimum-return-altitude">Return mode (Generic Vehicle) &gt; Minimum Return Altitude</a>.</li></ul><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><p>The RTL parameters are listed in <a href="./../advanced_config/parameter_reference#return-mode">Parameter Reference &gt; Return Mode</a>. If using a mission landing, only the <a href="#RTL_RETURN_ALT">RTL_RETURN_ALT</a> and <a href="#RTL_DESCEND_ALT">RTL_DESCEND_ALT</a> are relevant. The others are relevant if the destination is a rally point or the home location.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="RTL_TYPE"></a><a href="./../advanced_config/parameter_reference#RTL_TYPE">RTL_TYPE</a></td><td>Return type.</td></tr><tr><td><a id="RTL_APPR_FORCE"></a><a href="./../advanced_config/parameter_reference#RTL_APPR_FORCE">RTL_APPR_FORCE</a></td><td>[VTOL FW only] If set, PX4 only considers home or rally-point RTL destinations when a valid VTOL approach loiter is defined for that landing location. Mission landing patterns are unaffected.</td></tr><tr><td><a id="RTL_RETURN_ALT"></a><a href="./../advanced_config/parameter_reference#RTL_RETURN_ALT">RTL_RETURN_ALT</a></td><td>Return altitude in meters (default: 60m)If already above this value the vehicle will return at its current altitude.</td></tr><tr><td><a id="RTL_CONE_ANG"></a><a href="./../advanced_config/parameter_reference#RTL_CONE_ANG">RTL_CONE_ANG</a></td><td>Half-angle of the cone that defines the vehicle RTL return altitude. Values (in degrees): 0, 25, 45, 65, 80, 90. Note that 0 is &quot;no cone&quot; (always return at <code>RTL_RETURN_ALT</code> or higher), while 90 indicates that the vehicle must return at the current altitude or <code>RTL_DESCEND_ALT</code> (whichever is higher).</td></tr><tr><td><a id="RTL_DESCEND_ALT"></a><a href="./../advanced_config/parameter_reference#RTL_DESCEND_ALT">RTL_DESCEND_ALT</a></td><td>Minimum return altitude and altitude at which the vehicle will slow or stop its initial descent from a higher return altitude (default: 30m)</td></tr><tr><td><a id="RTL_LAND_DELAY"></a><a href="./../advanced_config/parameter_reference#RTL_LAND_DELAY">RTL_LAND_DELAY</a></td><td>Time to hover at <code>RTL_DESCEND_ALT</code> before landing (default: 0.5s) -by default this period is short so that the vehicle will simply slow and then land immediately. If set to -1 the system will loiter at <code>RTL_DESCEND_ALT</code> rather than landing. The delay is provided to allow you to configure time for landing gear to be deployed (triggered automatically).</td></tr><tr><td><a id="RTL_LOITER_RAD"></a><a href="./../advanced_config/parameter_reference#RTL_LOITER_RAD">RTL_LOITER_RAD</a></td><td>[Fixed-wing Only] The radius of the loiter circle (at <a href="#RTL_LAND_DELAY">RTL_LAND_DELAY</a>.</td></tr><tr><td><a id="MIS_TKO_LAND_REQ"></a><a href="./../advanced_config/parameter_reference#MIS_TKO_LAND_REQ">MIS_TKO_LAND_REQ</a></td><td>Specify whether a mission landing or takeoff pattern is <em>required</em>. Generally fixed-wing vehicles set this to require a landing pattern but VTOL do not.</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../flight_modes/return">Return Mode (Generic)</a></li><li><a href="./../flight_modes_mc/return">Return Mode (Multicopter)</a></li><li><a href="./../flight_modes_fw/return">Return Mode (Fixed-Wing)</a></li></ul>',28)])])}const u=a(n,[["render",l]]);export{f as __pageData,u as default};
